import{_ as t,o as a,c as o,ae as i}from"./chunks/framework.RRduUuAx.js";const h=JSON.parse('{"title":"ADR-002: Team Delegation to Host Skill","description":"","frontmatter":{},"headers":[],"relativePath":"reference/adrs/002.md","filePath":"reference/adrs/002.md"}'),n={name:"reference/adrs/002.md"};function r(s,e,l,c,d,m){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-002-team-delegation-to-host-skill" tabindex="-1">ADR-002: Team Delegation to Host Skill <a class="header-anchor" href="#adr-002-team-delegation-to-host-skill" aria-label="Permalink to &quot;ADR-002: Team Delegation to Host Skill&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>oh-my-codex implements team parallelism with 20+ files: a runtime orchestrator, tmux pane management, git worktree creation, worker spawning, and state synchronization. This infrastructure is necessary because Codex CLI operates independently without access to a host orchestration layer.</p><p>OpenClaw hosts such as oh-my-claudecode already provide <code>TeamCreate</code>/<code>TaskCreate</code>/<code>SendMessage</code> primitives for parallel agent execution. Rebuilding equivalent infrastructure in omm would duplicate existing capability and create maintenance burden.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>omm-team is a <strong>thin state-tracking bridge</strong>（状态追踪桥接层）that delegates actual parallel execution to the host environment&#39;s team skill.</p><p>The omm-team workflow:</p><ol><li>Receives task description and agent count</li><li>Writes tracking state (<code>key=team</code>, <code>current_phase=delegating</code>)</li><li>Invokes the host&#39;s team skill via <code>Skill()</code> delegation</li><li>Host team skill handles: <code>TeamCreate</code> → task decomposition → <code>TaskCreate</code> → workers → monitoring → <code>TeamDelete</code></li><li>On completion, omm-team writes terminal state</li></ol><p>omm-team&#39;s value is <strong>state tracking and workflow integration</strong> (e.g., <code>linked_ralph=true</code> for ralph↔team coordination), not parallel execution itself.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p><strong>Positive:</strong></p><ul><li>No duplicated parallelism infrastructure — uses battle-tested host implementation</li><li>Minimal code: one SKILL.md vs 20+ files in oh-my-codex</li><li>Consistent behavior: parallel execution matches what the host already provides</li><li>Integration coordination: <code>linked_ralph</code> flag enables ralph-team handoff</li></ul><p><strong>Negative:</strong></p><ul><li>Host dependency: omm-team requires a host that provides team primitives</li><li>Less control: cannot customize worker spawning, monitoring, or cleanup</li><li>Opaque execution: omm-team only tracks start/end, not individual worker progress</li></ul><p><strong>Trade-off accepted:</strong> omm gives up fine-grained control over parallel execution in exchange for zero-maintenance delegation to the host. If a host lacks team primitives, omm-team cannot function — this is acceptable because omm is designed for OpenClaw environments that provide these capabilities.</p>',15)])])}const u=t(n,[["render",r]]);export{h as __pageData,u as default};
